def stop_service(name,role,deadline):
 if name=='store':
  begin=deadline-60;result={'protocol':'NEW_PROTOCOL_EXIT60_L1','criterion_seconds':60,'owner':None,'pass':False,'begin_monotonic':begin,'deadline_monotonic':deadline,'measurement':'controller Stop call through original finish and strictgone, including IPC and diagnostic overhead'}
  try:
   item=services[name];nspid=int((base/role/(name+'.pid')).read_text());owner=owned_host_pid(nspid) if role=='worker' else None
   result['owner']=owner
   call(D+['exec','--user=2147:2147',cids[role],'/usr/bin/python3','-I','-c','import os,signal,sys;os.kill(int(sys.argv[1]),signal.SIGINT)',str(nspid)],3)
   stop_started=time.monotonic();captures=set()
   while item[0].poll() is None:
    assert time.monotonic()<deadline,'Store exit60 criterion exceeded';healthy();now=time.monotonic()
    for at in (10,20):
     if now<deadline and now-stop_started>=at and at not in captures:
      captures.add(at)
      try:record=m.process_stop_snapshot(owner,deadline)
      except Exception as error:record={'status':'DIAGNOSTIC_ERROR','error_type':type(error).__name__,'error':str(error)}
      record={'elapsed':time.monotonic()-stop_started,'owner':owner,'snapshot':record}
      try:save('store-stop-diagnostic-'+str(at)+'.json',record)
      except Exception as error:
       try:print(json.dumps({'event':'STORE_STOP_DIAGNOSTIC_SAVE_FAILED','at':at,'error_type':type(error).__name__}),flush=True)
       except Exception:pass
    time.sleep(.5)
   assert time.monotonic()<deadline,'Store exit60 finish deadline exceeded'
   finish(item,deadline)
   if owner:assert gone(owner),'Store exit60 owned process still present'
   completed=time.monotonic();assert completed<deadline,'Store exit60 completion verification exceeded criterion'
   result.update(elapsed=completed-begin,completion_monotonic=completed);result['pass']=True
   save('store-stop-exit60.json',result)
  except BaseException as error:
   result.update(elapsed=time.monotonic()-begin,error_type=type(error).__name__,error=str(error),failure_reason='criterion60_exceeded' if time.monotonic()>=deadline else 'normal_exit_or_strictgone_verification_failed')
   try:save('store-stop-exit60.json',result)
   except Exception as diagnostic_error:
    try:print(json.dumps({'event':'EXIT60_EVIDENCE_SAVE_FAILED','primary_error_type':type(error).__name__,'diagnostic_error_type':type(diagnostic_error).__name__}),flush=True)
    except Exception:pass
   raise
  return
